import sqlite3


def set_limit(conn: sqlite3.Connection, category_id: int, cents: int) -> None:
    conn.execute(
        "INSERT INTO budgets (category_id, monthly_limit) VALUES (?, ?)"
        " ON CONFLICT(category_id) DO UPDATE SET monthly_limit = excluded.monthly_limit",
        (category_id, cents),
    )


def get_limit(conn: sqlite3.Connection, category_id: int) -> int | None:
    row = conn.execute(
        "SELECT monthly_limit FROM budgets WHERE category_id = ?", (category_id,)
    ).fetchone()
    return None if row is None else int(row["monthly_limit"])


def list_limits(conn: sqlite3.Connection) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT c.id AS category_id, c.name AS category, b.monthly_limit AS monthly_limit"
        " FROM budgets b JOIN categories c ON c.id = b.category_id"
        " ORDER BY c.name"
    ).fetchall()

"""Money helpers. Amounts are carried around as integer cents."""

from decimal import Decimal, InvalidOperation

from ledgerly import config
from ledgerly.errors import ValidationError


def parse_amount(text: str) -> int:
    """Convert user text such as "12.5" into integer cents (1250)."""
    raw = (text or "").strip()
    if not raw:
        raise ValidationError("Amount is required")
    try:
        value = Decimal(raw)
    except InvalidOperation:
        raise ValidationError(f"Invalid amount: {raw!r}") from None
    if not value.is_finite():
        raise ValidationError(f"Invalid amount: {raw!r}")
    if value.as_tuple().exponent < -2:
        raise ValidationError("Amount cannot have more than 2 decimal places")
    if value <= 0:
        raise ValidationError("Amount must be greater than zero")
    return int(value * 100)


def format_cents(cents: int, currency: str = config.DEFAULT_CURRENCY) -> str:
    sign = "-" if cents < 0 else ""
    whole, fraction = divmod(abs(cents), 100)
    return f"{sign}{whole:,}.{fraction:02d} {currency}"

"""Terminal output. All user-facing text goes through this module."""

from typing import Sequence


def emit(text: str = "") -> None:
    print(text)


def emit_table(rows: Sequence[Sequence[object]], headers: Sequence[str]) -> None:
    cells = [[str(c) for c in row] for row in rows]
    widths = [len(h) for h in headers]
    for row in cells:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    def line(values: Sequence[str]) -> str:
        return "  ".join(v.ljust(w) for v, w in zip(values, widths)).rstrip()

    emit(line(list(headers)))
    emit(line(["-" * w for w in widths]))
    for row in cells:
        emit(line(row))
